if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }

var hexagrams = [];
var numCols = 8;
var numRows = 8;

function setup() {
    createCanvas(windowWidth, windowHeight, WEBGL);
    for (var i = 0; i < 64; i++) {
        var bars = [];
        for (var b = 0; b < 6; b++) {
            bars.push((i >> b) & 1);
        }
        hexagrams.push(bars);
    }
}

function draw() {
    background(10, 10, 15);

    var beat = (window.beatEnergy || 0.0);
    var low = (window.audioLow || 0.5);
    var t = frameCount * 0.012;

    rotateX(0.4 + sin(t * 0.4) * 0.2);
    rotateY(t * 0.2);

    var spacingX = 110;
    var spacingY = 110;
    var startX = -((numCols - 1) * spacingX) / 2;
    var startY = -((numRows - 1) * spacingY) / 2;

    for (var r = 0; r < numRows; r++) {
        for (var c = 0; c < numCols; c++) {
            var idx = r * numCols + c;
            var posX = startX + c * spacingX;
            var posY = startY + r * spacingY;

            var dCenter = dist(posX, posY, 0, 0);
            var posZ = sin(dCenter * 0.008 - t * 2) * 80 + beat * 120 * noise(c, r, frameCount * 0.02);

            push();
            translate(posX, posY, posZ);
            rotateZ((c + r) * 0.1 + t * 0.3);
            drawHexagram3D(hexagrams[idx], 40, 5, beat);
            pop();
        }
    }
}

function drawHexagram3D(bars, w, h, beat) {
    strokeWeight(1.5);
    for (var l = 0; l < 6; l++) {
        var yOffset = (l - 2.5) * (h + 4);
        var isSolid = (bars[l] === 1);

        if (isSolid) {
            stroke('#ffd700');
            fill('#ffb703');
            rect(-w / 2, yOffset, w, h);
        } else {
            stroke('#00f0ff');
            fill('#00b4d8');
            var halfW = (w - 6) / 2;
            rect(-w / 2, yOffset, halfW, h);
            rect(6 / 2, yOffset, halfW, h);
        }
    }
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}
